{
  "technical_and_design_decisions": [
    "All work is performed on the existing Spring XD codebase (Java 8 era toolchain, Spring Framework 4.x, Gradle build). Despite the generic Spring Framework 6 / Java 17 background in the specification, no framework or JDK upgrade is part of this increment.",
    "U1 (DEBS challenge) is implemented as XD stream definitions plus custom processor/sink modules where the remaining challenge queries require them.",
    "U2 is implemented as a new plan/job on the project's existing CI server that executes the Gradle 'install' target, with build notifications and result archiving.",
    "U4 reuses the existing jdbchdfs benchmark harness, extended to cover the new optimizations; U5 introduces JMH-based microbenchmarks for TupleBuilder.",
    "U6 introduces a single unescaped options payload (e.g., an options string or options file parsed internally by the job module) so users no longer escape each parameter; backward compatibility with existing per-parameter options is preserved.",
    "U7 introduces a ModuleDeployment SPI as Java interfaces with plugin registration (Spring-based discovery) plus a default implementation preserving current repository-backed behavior; stream and job deployment code paths are migrated to the SPI.",
    "U8 delivers a standalone Spring Boot-based ModuleRunner with per-module isolated classloaders, Boot externalized configuration, and pluggable message-bus binding (Redis/Rabbit/Kafka) so XD modules can run without xd-container.",
    "Every implementation activity includes unit tests; integration tests, benchmark runs, and documentation are included in the activities that explicitly name them."
  ],
  "assumptions": [
    "A single developer performs all the work; all estimates are effort in work-hours, not elapsed calendar duration.",
    "Required infrastructure is already available and accessible: CI server, Git repositories, Kafka, HDFS, Greenplum (GPDB), SQLServer, and Redis/Rabbit; only incremental setup/configuration effort is estimated.",
    "For U1, the 'remaining work' on the DEBS challenge is assumed to be roughly half of the full implementation (core design and initial streams already exist).",
    "Standard XD coding standards, code review, and merge processes apply; review/rework overhead is folded into the implementation estimates.",
    "Benchmark environments are representative and stable enough for meaningful before/after comparisons in U4 and U5.",
    "Third-party JDBC drivers for SQLServer and GPDB are licensed and available for U6 testing.",
    "Documentation effort is included within the relevant activities rather than estimated separately."
  ],
  "activities": [
    {
      "activity_id": "A1.1",
      "activity_name": "DEBS challenge: scope analysis and solution design",
      "activity_description": "U1: Review DEBS challenge requirements and current implementation state, define remaining queries, and design the XD stream topology and any custom modules needed to complete the challenge.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A1.2",
      "activity_name": "DEBS challenge: remaining implementation",
      "activity_description": "U1: Implement the remaining DEBS challenge processing logic and queries, wire the XD streams, and configure sources/sinks and custom modules.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A1.3",
      "activity_name": "DEBS challenge: validation and submission packaging",
      "activity_description": "U1: Functionally test the solution against challenge datasets, verify expected outputs/latency, fix defects, and package the submission for the deadline.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2.1",
      "activity_name": "CI build configuration for install target",
      "activity_description": "U2: Create a new CI plan/job that checks out the project and executes the Gradle 'install' target, including triggers, artifact handling, and failure notifications.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Install target verification and stabilization",
      "activity_description": "U2: Run the new CI build, investigate and fix failures surfaced by the install target, and stabilize the job so target expectations are continuously verified.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3.1",
      "activity_name": "XD + Kafka POC cleanup and packaging",
      "activity_description": "U3: Finalize the XD + Kafka proof-of-concept code and configuration for public consumption (cleanup, comments, sensible defaults, license headers).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3.2",
      "activity_name": "Samples repository publication and documentation",
      "activity_description": "U3: Write the README and architecture notes suitable for referencing in the XD blog, and publish the POC to the samples repository.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4.1",
      "activity_name": "jdbchdfs benchmark environment and script updates",
      "activity_description": "U4: Stand up/refresh the benchmark environment (source database and HDFS) and update benchmark scripts/configuration to include the new jdbchdfs optimizations.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4.2",
      "activity_name": "jdbchdfs benchmark execution and analysis",
      "activity_description": "U4: Execute the benchmark matrix, collect throughput/latency metrics, compare results against the pre-optimization baseline, and produce a findings report.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5.1",
      "activity_name": "TupleBuilder microbenchmark design and implementation",
      "activity_description": "U5: Design and implement JMH benchmarks exercising TupleBuilder hot paths (field addition, type conversion, tuple construction) with representative payloads.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5.2",
      "activity_name": "TupleBuilder bottleneck analysis and tuning",
      "activity_description": "U5: Profile benchmark runs to identify bottlenecks (e.g., allocations, reflection, copying) and implement performance optimizations with unit tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5.3",
      "activity_name": "TupleBuilder tuning validation",
      "activity_description": "U5: Re-run benchmarks to quantify improvements, confirm no functional regressions via the test suite, and document the tuning outcomes.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A6.1",
      "activity_name": "Simplified GPDB parameter UX: design and implementation",
      "activity_description": "U6: Design and implement a simplified way to pass Sqoop job parameters for GPDB without escaping each parameter (single options payload parsed internally), including unit tests and backward compatibility.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6.2",
      "activity_name": "Sqoop job testing with SQLServer and GPDB",
      "activity_description": "U6: Execute end-to-end Sqoop job tests against SQLServer and GPDB, identify and document UX differences between the two targets.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7.1",
      "activity_name": "Module deployment SPI design",
      "activity_description": "U7: Analyze current usage of the 'repository' abstraction for module deployment (vs stream/job definitions) and design the pluggable runtime SPI interfaces, contracts, and lifecycle.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7.2",
      "activity_name": "Module deployment SPI implementation and migration",
      "activity_description": "U7: Implement the SPI and a default implementation preserving current behavior, and migrate the stream/job module deployment code paths to the new SPI.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A7.3",
      "activity_name": "Module deployment migration testing and validation",
      "activity_description": "U7: Refactor existing tests to the SPI, add SPI-specific tests, and validate stream and job deployments end to end after the migration.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8.1",
      "activity_name": "Boot-based ModuleRunner architecture and design",
      "activity_description": "U8: Design the isolated Spring Boot-based ModuleRunner: module classloading/isolation model, externalized configuration, message-bus binding, and launch model for container-managed environments.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8.2",
      "activity_name": "Boot-based ModuleRunner implementation",
      "activity_description": "U8: Implement the Boot application, module resolution and launching with isolated classloaders, configuration binding, and transport binding so XD modules run without xd-container.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A8.3",
      "activity_name": "ModuleRunner integration testing and documentation",
      "activity_description": "U8: Write integration tests running modules via the ModuleRunner against a message bus, verify behavior in a container-managed setup, and document usage.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A9.1",
      "activity_name": "Increment integration and regression verification",
      "activity_description": "Cross-cutting: Merge all story branches, run the full XD build and test suite, smoke-test admin/runtime with the integrated changes, and resolve any cross-story integration issues.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 300
  }
}

